<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\ContactSubmission;use Illuminate\Http\Request;
class ContactController extends Controller { public function index(Request $r){$q=ContactSubmission::query()->when($r->status,fn($x,$v)=>$x->where('status',$v))->when($r->search,fn($x,$v)=>$x->where(fn($y)=>$y->where('name','like',"%$v%")->orWhere('phone','like',"%$v%")->orWhere('email','like',"%$v%")))->latest();return response()->json($q->paginate(50));} public function update(Request $r,ContactSubmission $contact){$d=$r->validate(['status'=>'nullable|in:New,Read,Contacted,Resolved,Archived','admin_notes'=>'nullable|string|max:5000']);if(isset($d['status'])){$d['read_at']=in_array($d['status'],['Read','Contacted','Resolved','Archived'])?($contact->read_at??now()):null;if(in_array($d['status'],['Contacted','Resolved']))$d['contacted_at']=$contact->contacted_at??now();if($d['status']==='Archived')$d['archived_at']=$contact->archived_at??now();}$contact->update($d);return response()->json(['data'=>$contact->fresh()]);} public function destroy(ContactSubmission $contact){$contact->delete();return response()->json(['message'=>'Contact deleted.']);} }
